angle_el = angle_el_FOC_20kHz;

% Clarke-Park transformation of phase currents
TC = 2/3*[1 -0.5 -0.5;
          0 sqrt(3)/2 -sqrt(3)/2];

TP = [ cos(angle_el)   sin(angle_el);
      -sin(angle_el)  cos(angle_el)];
  
i_alpha_beta = zeros(2,l);
        
for i=1:l
i_alpha_beta(1:2,i) = TC*[i_ph(1,i,1), i_ph(2,i,1), i_ph(3,i,1)]';
end

i_dq = zeros(2,l);

for i=1:l
    i_dq(1:2,i) = [ cos(angle_el(i))   sin(angle_el(i));
                   -sin(angle_el(i))  cos(angle_el(i))] * i_alpha_beta(1:2,i);
end

figure
plot(time(1,:),i_alpha_beta(1,:))
hold on
plot(time(1,:),i_alpha_beta(2,:))

figure
plot(time(1,:),i_dq(1,:))
hold on
plot(time(1,:),i_dq(2,:))
plot(time(1,:),angle_el(:))
